package com.samadhansetu.Service;
import com.samadhansetu.Repository.DepartmentRepository; import com.samadhansetu.dto.UniversityRoutingResponseDto; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class UniversityRoutingService{private final DepartmentRepository repo;private static final Map<String,List<String>> TERMS=Map.ofEntries(Map.entry("Education",List.of("education","computer","science","engineering","teacher")),Map.entry("Agriculture",List.of("agriculture","agronomy","horticulture","agri")),Map.entry("Healthcare",List.of("medical","medicine","health","nursing","pharmacy")),Map.entry("Water Resources",List.of("civil","water","environmental","hydrology")),Map.entry("Environment",List.of("environment","ecology","forest","civil")),Map.entry("Energy",List.of("electrical","energy","power","mechanical")),Map.entry("Urban Development",List.of("civil","architecture","urban","planning")),Map.entry("Accessibility",List.of("computer","mechanical","civil","architecture")),Map.entry("Public Administration",List.of("public administration","management","social science")),Map.entry("Rural Livelihoods",List.of("rural development","management","economics","agriculture")));public List<UniversityRoutingResponseDto> route(String category){String c=category==null?"":category.trim();List<String> terms=TERMS.getOrDefault(c,List.of(c.toLowerCase(Locale.ROOT)));List<UniversityRoutingResponseDto> out=new ArrayList<>();for(var d:repo.findAll()){String n=d.getName()==null?"":d.getName().toLowerCase(Locale.ROOT);int score=0;for(String t:terms)if(!t.isBlank()&&n.contains(t.toLowerCase(Locale.ROOT)))score++;if(score>0){var u=d.getUniversity();out.add(UniversityRoutingResponseDto.builder().universityId(u.getId()).universityName(u.getName()).universityCode(u.getCode()).location(u.getLocation()).departmentId(d.getId()).departmentName(d.getName()).score(score).reason("Department matches AI category: "+c).build());}}out.sort(Comparator.comparingInt(UniversityRoutingResponseDto::getScore).reversed());return out;}}
